import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 5 — Spec First","description":"","frontmatter":{"source":"weeks/05-spec-first/README.md"},"headers":[],"relativePath":"weeks/05-spec-first/index.md","filePath":"weeks/05-spec-first/index.md"}'),s={name:"weeks/05-spec-first/index.md"};function i(n,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-5--spec-first" tabindex="-1">Week 5 — Spec First <a class="header-anchor" href="#week-5--spec-first" aria-label="Permalink to &quot;Week 5 — Spec First&quot;">​</a></h1><blockquote><p>A spec is the prompt for the whole project.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Read this page and the <a href="./example-spec.html">example spec</a>. Choose two or three ideas for Project 1 (the <a href="./lab.html#part-1--size-your-project-1-idea-5-min">lab&#39;s idea list</a> has some) and sketch the main screen of your favorite on paper: boxes and labels only</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk on the one-page spec, app builders and the 70% problem; a live Goldfish test; then you write <code>SPEC.md</code> for Project 1 by hand</td></tr><tr><td><strong>Studio B</strong></td><td>A <strong>peer spec review</strong> (written up on Canvas), the <strong>Goldfish test</strong> of your own spec, and your spec moves into its own repository. Exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>A public Project 1 repository with a revised <code>SPEC.md</code>, <code>PROMPTS.md</code> (two Goldfish runs), <code>TESTS.md</code> (manual tests and a logic plan) and your first automated test, still failing · on Canvas: your written spec review and your reflection. Details: <a href="./homework.html">homework</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: none; you build next week · 🟡 AI limited: the Goldfish test (the AI reads your spec and asks; it never rewrites it), and asking which edge cases your tests miss · 🔴 AI off: the first draft of <code>SPEC.md</code>, the peer review, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../templates/SPEC.html">SPEC template</a> · <a href="./../../templates/TESTS.html">TESTS template</a> · <a href="./../../projects/project-1-useful-tool.html">Project 1 brief</a> · <a href="./../../resources/prompt-patterns.html#18-the-goldfish-test">The Goldfish test pattern</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>A public Project 1 repository with a complete <code>SPEC.md</code>. Week 6 builds from it</td></tr><tr><td><strong>Time</strong></td><td>Studios 2 × 75 min · outside about 6 h (prep up to 30 min, homework core about 3 h, project time about 2 h, <code>PROMPTS.md</code> and reflection about 30 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Write a one-page <code>SPEC.md</code>: problem, user, prioritized user stories, constraints, out of scope, wireframe.</li><li>Write <strong>WHEN … THE APP SHALL …</strong> criteria that a stranger can check by using the app, including edge cases.</li><li>Review a classmate&#39;s spec: predict the app, find untestable criteria, name a missing edge case.</li><li>Run the Goldfish test, and revise the spec from what a fresh chat asked or got wrong.</li><li>Explain what an app builder generates behind its preview, and why the &quot;70% problem&quot; makes criteria matter.</li><li>Turn criteria into manual tests, and the rules inside them into examples for automated tests.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Finish the week 4 homework.</li><li>☐ Choose two or three ideas for <strong>Project 1: A Tool I&#39;d Actually Use</strong>: single user, data saved in the browser, no login, no real data about other people (<a href="./lab.html#part-1--size-your-project-1-idea-5-min">idea list</a>, <a href="./../../projects/project-1-useful-tool.html">more ideas</a>).</li><li>☐ Sketch the main screen of your favorite on paper. Bring the paper or a photo.</li><li>☐ Read the <a href="./example-spec.html">example spec</a>, including &quot;Why this spec works&quot;.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-05.html" target="_blank" rel="noreferrer">slides</a>) · live demo: the Goldfish test on a weak and a strong spec · lab: size your idea, write <code>SPEC.md</code> (🔴 AI off) · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · lab: peer spec review, the Goldfish test · project time: give your spec a home · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="./example-spec.html">Example spec</a></td><td>A complete model spec, notes on why it works, and the same idea written weakly</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-05.html" target="_blank" rel="noreferrer">Slides</a></td><td>Studio A&#39;s concept talk</td></tr><tr><td>Templates: <a href="./../../templates/SPEC.html">SPEC</a> · <a href="./../../templates/PROMPTS.html">PROMPTS</a> · <a href="./../../templates/TESTS.html">TESTS</a></td><td>Copied into your Project 1 repository</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>Working on your own? Read this section, then do the <a href="./lab.html">lab</a>; the <a href="./../../resources/self-paced.html">self-paced path</a> replaces the pair activities.</p><p><strong>A spec is the prompt for the whole project.</strong> Before any prompt, you write one page that says who the tool is for, what it must do, and what it won&#39;t do. Everything that reads it later (a classmate, an app builder, a chat assistant and, in week 11, an agent) builds from the same page. Writing well matters: in a 2026 study of 100 students, both writing skill and computing grades predicted how well students vibe-coded (<a href="https://arxiv.org/abs/2603.14133" target="_blank" rel="noreferrer">Thorgeirsson et al.</a>).</p><p><strong><a href="./../../resources/glossary.html#user-story">User stories</a> and priorities.</strong> Each feature is written from the user&#39;s side: <em>As a student, I want to …, so that …</em>. Mark each one <strong>MUST</strong> (useless without it), <strong>SHOULD</strong> or <strong>COULD</strong>. The MUSTs make your <strong><a href="./../../resources/glossary.html#mvp">MVP</a></strong>, the <em>minimum viable product</em>: the smallest version that is actually useful. Three to five MUSTs is plenty for Project 1.</p><p><strong><a href="./../../resources/glossary.html#acceptance-criterion">Acceptance criteria</a> you can check by using the app.</strong> <strong>WHEN</strong> I press Add with an empty box, <strong>THE APP SHALL</strong> add nothing and show &quot;Please type a name&quot;. The format comes from <a href="./../../resources/glossary.html#ears">EARS</a>, which AWS&#39;s Kiro tool uses to turn requirements into specs for AI (<a href="https://kiro.dev/blog/introducing-kiro/" target="_blank" rel="noreferrer">Kiro</a>). &quot;Easy to use&quot; is not a criterion: nobody can check it. Include <strong><a href="./../../resources/glossary.html#edge-case">edge cases</a></strong>, the unusual situations where bugs live: empty input, duplicates, reloading, a small screen.</p><p><strong>Out of scope is a feature.</strong> Naming what you are <em>not</em> building (login, sync, charts, dark mode) stops you, and the AI, from wandering. A <strong><a href="./../../resources/glossary.html#wireframe">wireframe</a></strong>, a rough sketch of the screen, does the same for layout.</p><p><strong>Say what, not how.</strong> If you program, you&#39;ll be tempted to put functions or data structures into the spec. Leave them out: a criterion describes what a user sees. Only the Constraints section talks about technology. Your instincts help with boundaries: &quot;40 characters is accepted; 41 is refused&quot; is a sharp criterion.</p><p><strong>The Goldfish test.</strong> A fresh chat knows nothing about you or your idea, like a goldfish. Paste only your spec into a new chat and ask what it would build and what it would have to ask. Every question is a gap that every later builder and agent will fall into too. Fix the spec, not the chat. Michigan&#39;s AI software engineering course uses the same fresh-session test (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">EGM</a>).</p><p><strong>What <a href="./../../resources/glossary.html#app-builder">app builders</a> are.</strong> Google AI Studio&#39;s Build mode, Bolt, Lovable and v0 turn a description into a whole running app. Behind the preview is a real project: often a <strong><a href="./../../resources/glossary.html#framework">framework</a></strong> such as React (a large library that shapes how the app is written), a <strong><a href="./../../resources/glossary.html#build-step">build step</a></strong>, and sometimes a server, a database and a login. Google documents that AI Studio Build creates React and Node apps and can add a database and login automatically (<a href="https://ai.google.dev/gemini-api/docs/aistudio-build-mode" target="_blank" rel="noreferrer">Google AI Studio docs</a>). Next week you feed one your spec.</p><p><strong>The 70% problem.</strong> Addy Osmani describes people who get 70% of the way very fast with AI, then stall on the last 30% (edge cases, fixes that break something else) because they have no mental model of the code (<a href="https://addyo.substack.com/p/the-70-problem-hard-truths-about" target="_blank" rel="noreferrer">Osmani</a>). Your criteria are how you find that 30%. This week you turn them into manual tests, and the rules inside them (checks on input, calculations, dates) into a <strong>logic plan</strong> of example inputs and expected outputs. Next week those become automated tests, written before the code.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>The week 5 exit ticket is 🔴 AI off and graded on completion, not correctness. It opens with a look-back question about your week 3 game, answered from memory. Its central question: <em>rewrite a vague requirement as a criterion a stranger could check.</em> To check yourself first:</p><ul><li>Explain how a stranger would test one of your criteria in under a minute.</li><li>Name two edge cases in your spec and why each could break.</li><li>Name one Goldfish question and the line it made you change.</li><li>Say what an app builder generates behind its preview, and why criteria matter more when you can&#39;t read the code.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>Core (about 5 hours with project time): finish your spec review; revise <code>SPEC.md</code> and rerun the Goldfish test; manual tests and a logic plan in <code>TESTS.md</code>; your first automated test, failing; your reflection. Details: <a href="./homework.html">homework</a>. Project 1 <strong>version 1</strong> is due before week 7 Studio A and the <strong>final</strong> before week 9 Studio A (<a href="./../../projects/project-1-useful-tool.html">Project 1 brief</a>, <a href="./../../assessment/rubrics.html#project-1">rubric</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If this fails</th><th>Do this</th></tr></thead><tbody><tr><td>Your chat assistant (for the Goldfish test)</td><td>Switch to a fallback in the <a href="./../../TOOLS.html">Tool Handout</a>, open a fresh chat and paste only your <code>SPEC.md</code></td></tr><tr><td>The fresh chat seems to know you already</td><td>Your assistant&#39;s memory is on. Use a temporary chat, or turn memory off (<a href="./../../setup/privacy-settings.html">privacy settings</a>)</td></tr><tr><td>GitHub is down, or you can&#39;t create a repository</td><td>Keep your spec in a document and create the repository later (<a href="./../../setup/github-basics.html">GitHub basics</a>)</td></tr><tr><td>Canvas is down</td><td>Write your review in a document and paste it into Canvas when it&#39;s back</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Kiro&#39;s guide to feature specs, with more EARS examples: <a href="https://kiro.dev/docs/specs/feature-specs/" target="_blank" rel="noreferrer">https://kiro.dev/docs/specs/feature-specs/</a></li><li>GitHub&#39;s Spec Kit, a spec → plan → tasks → implement workflow for AI agents: <a href="https://github.blog/ai-and-ml/generative-ai/spec-driven-development-with-ai-get-started-with-a-new-open-source-toolkit/" target="_blank" rel="noreferrer">GitHub blog</a></li><li>The course <a href="./../../resources/reading-list.html">reading list</a> and <a href="./../../resources/prompt-patterns.html">prompt patterns</a></li></ul>',32)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
